-- A private, single-use approval matches the ID and email generated by the
-- server before Auth inserts the user. Never trust user-editable metadata.
BEGIN;
CREATE TABLE public.beta_signup_authorizations (
  user_id uuid PRIMARY KEY,
  email text NOT NULL,
  expires_at timestamptz NOT NULL
);
ALTER TABLE public.beta_signup_authorizations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.beta_signup_authorizations FROM PUBLIC, anon, authenticated;
GRANT SELECT, DELETE ON public.beta_signup_authorizations TO service_role;
CREATE OR REPLACE FUNCTION public.authorize_beta_signup(p_user_id uuid, p_email text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  IF p_user_id IS NULL OR p_email IS NULL OR length(p_email)>255
     OR p_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' THEN
    RAISE EXCEPTION 'INVALID_SIGNUP_APPROVAL';
  END IF;
  DELETE FROM public.beta_signup_authorizations WHERE expires_at <= now();
  INSERT INTO public.beta_signup_authorizations(user_id,email,expires_at)
    VALUES(p_user_id,lower(btrim(p_email)),now()+interval '5 minutes');
END;
$$;
REVOKE ALL ON FUNCTION public.authorize_beta_signup(uuid,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.authorize_beta_signup(uuid,text) TO service_role;

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp AS $$
DECLARE approved_id uuid;
BEGIN
  IF NULLIF(LTRIM(new.phone, '+'), '') IS NULL THEN
    DELETE FROM public.beta_signup_authorizations
    WHERE user_id=new.id AND email=lower(new.email) AND expires_at>now()
    RETURNING user_id INTO approved_id;
    IF approved_id IS NULL
       AND COALESCE(new.raw_app_meta_data->>'beta_web_approved','')<>'true'
       AND COALESCE(new.raw_app_meta_data->>'google_play_reviewer','')<>'true' THEN
      RAISE EXCEPTION 'Email registration is not enabled for this account';
    END IF;
  END IF;
  INSERT INTO public.users(id,phone,email,name)
  VALUES(new.id,NULLIF(LTRIM(new.phone,'+'),''),new.email,'')
  ON CONFLICT(id) DO NOTHING;
  RETURN new;
END;
$$;
REVOKE ALL ON FUNCTION public.handle_new_user() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.handle_new_user() TO service_role;
COMMIT;
